        pool, toTransform, topLeft, topRight, bottomRight, bottomLeft);
  }

  @Override
  public boolean equals(Object o) {
    if (o instanceof GranularRoundedCorners) {
      GranularRoundedCorners other = (GranularRoundedCorners) o;
