public static int getBytesPerPixel(@Nullable Bitmap.Config config) {
  // A bitmap by decoding a GIF has null "config" in certain environments.
  if (config == null) {
    config = Bitmap.Config.ARGB_8888;
  }

  switch (config) {
    case ALPHA_8:
      return 1;
    case RGB_565:
    case ARGB_4444:
      return 2;
    case RGBA_F16:
      return 8;
    case ARGB_8888:
    default:
      return 4;
  }
}

